package dev.garciajg.oritechextensions.client;

import dev.garciajg.oritechextensions.paint.PaintColors;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.texture.MissingTextureAtlasSprite;
import net.minecraft.client.renderer.texture.TextureAtlasSprite;
import net.minecraft.world.inventory.InventoryMenu;
import rearth.oritech.util.ColorableMachine.ColorVariant;

import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Finds the painted version of a block texture in the block atlas.
 * <p>
 * The painted textures are generated by vanilla's "paletted_permutations" atlas source
 * (assets/minecraft/atlases/blocks.json in this mod), which recolours each listed texture with the colour swap
 * Oritech uses for its own paints. A texture {@code ns:block/x} gets painted variants named
 * {@code ns:block/x_paint_<colour>}. Textures that weren't listed simply have no painted variant.
 * <p>
 * One instance per model bake, shared by all wrapped models, so lookups never outlive the atlas they came from.
 */
final class PaintedSprites {

    private record Key(TextureAtlasSprite original, ColorVariant variant) {
    }

    private final ConcurrentHashMap<Key, Optional<TextureAtlasSprite>> cache = new ConcurrentHashMap<>();

    Optional<TextureAtlasSprite> find(TextureAtlasSprite original, ColorVariant variant) {
        return cache.computeIfAbsent(new Key(original, variant), key -> {
            var atlas = Minecraft.getInstance().getModelManager().getAtlas(InventoryMenu.BLOCK_ATLAS);
            var name = original.contents().name().withSuffix(PaintColors.spriteSuffix(variant));
            var sprite = atlas.getSprite(name);
            return sprite.contents().name().equals(MissingTextureAtlasSprite.getLocation()) ? Optional.empty() : Optional.of(sprite);
        });
    }
}
